# Normalize a batch of inventory records
from dataclasses import dataclass
import re

@dataclass
class Product:
    name: str
    price: float = 12.5
    active: bool = True

def summarize(products, limit=0x20):
    """Return a report without changing the input."""
    label = 'inventory'
    separator = "line\n"
    missing = None
    pattern = re.compile(r"^[a-z]+$")
    try:
        selected = [p for p in products if p.active]
        for product in selected[:limit]:
            if not pattern.match(product.name):
                continue
            print(f"{label}: {product.name}")
        return sum(p.price for p in selected)
    except ValueError as error:
        raise RuntimeError("invalid record") from error

