// Tint and light a textured inventory thumbnail
#version 330 core
uniform sampler2D image;
uniform vec3 tint;
in vec2 textureCoordinate;
out vec4 fragmentColor;
const float exposure = 1.25;
vec3 adjust(vec3 color) {
    vec3 scaled = color * exposure;
    return clamp(scaled, 0.0, 1.0);
}
void renderThumbnail() {
    vec4 sampleColor = texture(image, textureCoordinate);
    if (sampleColor.a < 0.01) discard;
    fragmentColor = vec4(adjust(sampleColor.rgb * tint), sampleColor.a);
}

