// Inventory: validate and normalize request records
const scale = 1.5e2;
const mask = 0xff;
const label = 'inventory';
const fallback = null;
const active = false;
const pattern = /^[a-z]+$/i;
async function loadRecords(endpoint) {
  const response = await fetch(endpoint);
  const records = await response.json();
  return records.filter(record => record.enabled);
}
function summarize(records = []) {
  const result = { count: records.length, total: 0 };
  for (const record of records) {
    if (!pattern.test(record.name)) continue;
    result.total += record.price * scale;
  }
  return `${label}: ${result.total}`;
}
