let service = "inventory";
Requests
| where Timestamp > ago(1d)
| where ServiceName == service
| extend DurationMs = toreal(Duration)
| where DurationMs > threshold
| summarize Count=count(), Average=avg(DurationMs) by bin(Timestamp, 1h), Region
| order by Timestamp asc
| project Timestamp, Region, Count, Average
;
let failures = Requests | where Success == false;
failures
| summarize Total=count() by ErrorCode
| top 10 by Total

